void ProduceRegister::clear (Inventory& inv) {
    std::memset(inv.m_v, 0, sizeof(inv.m_v));
}

void ProduceRegister::clear (CityYields& yld) {
    std::memset(yld.m_v, 0, sizeof(yld.m_v));
}

void ProduceRegister::apply (Inventory& inv, CityYields& yld, const EffectCtx& ctx) {
    if (GROUP_N == 0) {
        clamp_i16_arr(inv.m_v, INV_N);
        clamp_i16_arr(yld.m_v, YIELD_N);
        return;
    }
    for (u16 i = 0; i < GROUP_N; ++i) {
        const ProduceGroup& g = s_group[i];
        if (!produce_src_active(g.m_enabler, ctx)) {
            continue;
        }
        if (!group_can_pay(g, inv)) {
            continue;
        }
        for (u8 s = 0; s < g.m_slot_n; ++s) {
            apply_slot(inv, yld, g.m_slots[s]);
        }
    }
    clamp_i16_arr(inv.m_v, INV_N);
    clamp_i16_arr(yld.m_v, YIELD_N);
}

const ProduceGroup* ProduceRegister::groups () {
    return s_group;
}

u16 ProduceRegister::group_count () {
    return GROUP_N;
}

